WITH qualified AS (SELECT mktcode,tgtcode FROM `newzl`.`hsj_stock_hq_basic` WHERE bizdate>=DATE_ADD(DATE_SUB('2026-04-14', INTERVAL '6' MONTH), INTERVAL '1' DAY) AND bizdate<='2026-04-14' GROUP BY mktcode,tgtcode HAVING AVG(volume)>0) SELECT b.mktcode,b.tgtcode,b.bizdate FROM `newzl`.`hsj_stock_hq_basic` b JOIN qualified q ON q.mktcode=b.mktcode AND q.tgtcode=b.tgtcode WHERE b.bizdate='2026-04-14';
